/**
 * Dossiers temporaires autorisés au nettoyage, assistant 28.
 *
 * C'est une LISTE BLANCHE, et c'est tout l'objet de la règle : l'utilisateur
 * choisit quelles entrées traiter, jamais un chemin de son cru. Chaque entrée
 * se résout depuis une variable d'environnement ou un dossier connu de
 * Windows ; aucune n'est écrite en dur avec une lettre de lecteur.
 *
 * `profondeur` dit jusqu'où descendre. `systeme` marque les entrées situées
 * dans l'arborescence de Windows : elles portent l'avertissement renforcé.
 */
export const TEMPORAIRES_AUTORISES = [
  { cle: 'TempUtilisateur', expr: '$env:TEMP', libelle: 'Temporaires de la session (TEMP)', systeme: false },
  { cle: 'TempWindows', expr: "(Join-Path $env:SystemRoot 'Temp')", libelle: 'Temporaires de Windows (Windows\\Temp)', systeme: true },
  { cle: 'CacheInternet', expr: "(Join-Path $env:LOCALAPPDATA 'Microsoft\\Windows\\INetCache')", libelle: 'Cache des fichiers Internet temporaires', systeme: false },
  { cle: 'RapportsErreurs', expr: "(Join-Path $env:LOCALAPPDATA 'CrashDumps')", libelle: 'Vidages memoire d applications (CrashDumps)', systeme: false },
  { cle: 'LivraisonMaj', expr: "(Join-Path $env:SystemRoot 'SoftwareDistribution\\Download')", libelle: 'Telechargements de Windows Update', systeme: true },
];

/**
 * En-tête commun des assistants de ce lot qui écrivent un journal.
 *
 * Un assistant qui modifie l'état sans laisser de trace est ingérable : au
 * moindre doute, personne ne peut dire ce qui a été fait. Le journal est écrit
 * AVANT l'action, et son échec bloque l'action.
 */
export function blocJournalAvant(cheminVar, sujet, gardeVar) {
  // LE GARDIEN ENTOURE L'ECRITURE, il ne la corrige pas apres coup.
  //
  // La version precedente appelait New-Item et Set-Content, PUIS remettait
  // $journalOk a $false si le gardien avait refuse le chemin. L'action
  // principale etait bien bloquee — mais le dossier et le fichier de journal
  // avaient DEJA ete crees, a un chemin que le gardien venait de refuser.
  // Un refus qui laisse un effet de bord n'est pas un refus.
  //
  // Le resultat du gardien est donc maintenant la condition du bloc
  // d'ecriture : si elle est fausse, aucun New-Item, aucun Set-Content,
  // aucun Add-Content n'est atteint.
  if (!gardeVar) throw new Error('blocJournalAvant : le nom de la variable du gardien est obligatoire.');
  return [
    "# --- Journal, ECRIT AVANT l'action ------------------------------------------------",
    "# Un assistant qui modifie l'etat sans laisser de trace est ingerable. Le",
    "# journal est donc ecrit AVANT, et son echec BLOQUE l'action : pas de",
    '# modification non tracable.',
    '#',
    "# Le gardien de chemin ENTOURE l'ecriture : un chemin refuse ne produit",
    '# aucune creation de dossier et aucun fichier. Zero effet de bord.',
    '$journalOk = $false',
    '$journalFichier = $null',
    `if (-not ${gardeVar}) {`,
    "  [void](Add-KjemoResultat -Categorie 'Journal' -Controle 'Fichier' -Etat 'PROBLEME' -Valeur 'chemin refuse par le gardien' -Commentaire 'Aucun dossier et aucun fichier de journal n''ont ete crees : le chemin a ete refuse AVANT toute ecriture. L''action sera bloquee.')",
    `} elseif (-not [string]::IsNullOrWhiteSpace(${cheminVar})) {`,
    '  try {',
    `    if (-not (Test-Path -LiteralPath ${cheminVar})) { [void](New-Item -ItemType Directory -Path ${cheminVar} -ErrorAction Stop) }`,
    `    $journalFichier = Join-Path ${cheminVar} ('kjemo-${sujet}-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.txt')`,
    '    $entete = @()',
    `    $entete += '=== KJEMO — ${sujet} ==='`,
    "    $entete += ('Date      : ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'))",
    "    $entete += ('Poste     : ' + $env:COMPUTERNAME)",
    "    $entete += ('Session   : ' + $env:USERNAME)",
    "    $entete += ('Elevation : ' + [string]$KjemoEleve)",
    '    Set-Content -LiteralPath $journalFichier -Value $entete -Encoding UTF8 -ErrorAction Stop',
    '    $journalOk = $true',
    "    [void](Add-KjemoResultat -Categorie 'Journal' -Controle 'Fichier' -Etat 'OK' -Valeur $journalFichier)",
    '  } catch {',
    '    $journalFichier = $null',
    "    [void](Add-KjemoResultat -Categorie 'Journal' -Controle 'Fichier' -Etat 'PROBLEME' -Valeur ([string]$_.Exception.Message) -Commentaire 'Sans journal, aucune modification ne sera tentee.')",
    '  }',
    '} else {',
    "  [void](Add-KjemoResultat -Categorie 'Journal' -Controle 'Fichier' -Etat 'PROBLEME' -Valeur 'aucun dossier fourni' -Commentaire 'Le journal est obligatoire avant toute modification.')",
    '}',
  ].join('\n');
}

/**
 * Le bloc qui dit, dans chaque script de ce lot, ce que l'assistant ne fera
 * pas aux données personnelles.
 *
 * Il est répété exprès. Un technicien qui lit un script de nettoyage veut
 * trouver cette liste dans le script lui-même, pas dans une fiche restée dans
 * le navigateur.
 */
export function blocDonneesPersonnelles() {
  return [
    "Write-Host ''",
    "Write-Host '--- Ce que ce script ne touche jamais ---'",
    "Write-Host 'Ni mots de passe, ni cookies, ni sessions, ni jetons.'",
    "Write-Host 'Ni favoris, ni historique, ni extensions, ni profils.'",
    "Write-Host 'Ni Documents, ni Bureau, ni Telechargements.'",
    "Write-Host 'Ni .git, ni .env, ni base de donnees, ni sauvegarde.'",
    "Write-Host 'Aucune application n''est fermee, aucun service n''est arrete.'",
  ].join('\n');
}

/**
 * Les variables du script, posees a partir des parametres.
 *
 * DEFAUT TROUVE PAR LE BANC D'EXECUTION, pas par relecture : blocParametres()
 * ne construit que l'objet $KjemoParametres, destine au rapport. Il n'affecte
 * AUCUNE variable. Un corps qui lit $Mode ou $Service sans les avoir poses
 * travaille donc sur des variables vides — le script bloque, ce qui est sans
 * danger, mais il ne fait plus rien et personne ne comprend pourquoi.
 *
 * Ce helper existe pour que l'oubli ne se reproduise pas : les memes paires
 * servent au rapport ET aux variables, et les deux viennent d'un seul endroit.
 */
function blocVariables(paires) {
  return paires.map(([cle, expr]) => `$${cle} = ${expr}`).join('\n');
}

/** Champ de journal, commun aux assistants qui modifient quelque chose. */
function champJournal(id, aide) {
  return {
    id,
    label: 'Dossier du journal',
    type: 'text',
    default: 'C:\\Kjemo\\Journaux',
    placeholder: 'C:\\Kjemo\\Journaux',
    help: aide,
  };
}

/** Champ de confirmation écrite, à recopier exactement. */
function champConfirmation(id, phrase, aide) {
  return {
    id,
    label: 'Confirmation écrite',
    type: 'text',
    default: '',
    placeholder: phrase,
    help: `${aide} Pour l’autoriser, retaper exactement : ${phrase}`,
  };
}

